import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Dashboards","description":"","frontmatter":{"title":"Dashboards","covers":{"screens":["SCR-024","SCR-056"],"stories":["US-055","US-058","US-059","US-060","US-062"]}},"headers":[],"relativePath":"usage/dashboards.md","filePath":"usage/dashboards.md"}`),a={name:`usage/dashboards.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="dashboards" tabindex="-1">Dashboards <a class="header-anchor" href="#dashboards" aria-label="Permalink to “Dashboards”">​</a></h1><p>A dashboard gives readers a structured view of the architecture. It arranges <strong>widgets</strong> in a grid of 12 columns: text widgets with formatted notes, and table widgets that show the rows of a <a href="./catalogs">catalog</a>. You need the permission <code>entity:read</code> (for example the role <code>viewer</code>) to see dashboards and to create personal ones; shared dashboards need <code>dashboard:manage</code> (role <code>enterprise-architect</code>).</p><p>There are two kinds of dashboards:</p><ul><li><strong>Shared</strong> dashboards are visible to every reader of the instance. Every person with <code>dashboard:manage</code> can change and delete every shared dashboard.</li><li><strong>Personal</strong> dashboards are visible to you only. Nobody else sees them in a list, and their address answers <em>The dashboard does not exist or you may not see it</em>. The exception are administrators with the permission <code>settings:manage</code>: they see the personal dashboards of other persons in the list, marked with the owner, and can read them, but never change or delete them.</li></ul><p>Service accounts have no access to dashboards.</p><h2 id="the-page-dashboards" tabindex="-1">The page Dashboards <a class="header-anchor" href="#the-page-dashboards" aria-label="Permalink to “The page Dashboards”">​</a></h2><p>Choose <em>Dashboards</em> in the header. The page lists the dashboards you may see with their visibility (<em>Shared</em> or <em>Personal</em>), the owner and the number of widgets. Choose a dashboard to open it.</p><h2 id="create-a-dashboard" tabindex="-1">Create a dashboard <a class="header-anchor" href="#create-a-dashboard" aria-label="Permalink to “Create a dashboard”">​</a></h2><ol><li><p>Choose <em>Create dashboard</em> on the page <em>Dashboards</em>.</p></li><li><p>Fill in the dialog:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required, 1 to 200 characters; unique among the shared dashboards and among your personal dashboards, regardless of upper and lower case</td></tr><tr><td>Description</td><td>optional, up to 1000 characters</td></tr><tr><td>Visibility</td><td><em>Shared</em>: visible to every reader (needs the permission to manage dashboards); <em>Personal</em>: visible to you only</td></tr></tbody></table></li><li><p>Choose <em>Create dashboard</em>. The new dashboard opens with the notice &quot;No widgets yet. Add widget.&quot;</p></li></ol><p>If the name is already taken, the dialog says so. Without the permission to manage dashboards, <em>Shared</em> is not selectable.</p><h2 id="read-a-dashboard" tabindex="-1">Read a dashboard <a class="header-anchor" href="#read-a-dashboard" aria-label="Permalink to “Read a dashboard”">​</a></h2><p>A dashboard shows its widgets at their positions. The data is computed each time you open it, with your own permissions: a table widget shows the catalog as you may see it, including locked columns (see <a href="./../administration/property-visibility">Property visibility</a>).</p><ul><li>A <strong>text widget</strong> shows its Markdown as formatted text.</li><li>A <strong>table widget</strong> shows the rows of its catalog, with the columns of its saved view if it has one. Below the table, <em>Page 1 of 5 · 47 entries</em> and the pagination move between pages.</li><li>A widget whose catalog is gone or not visible to you shows <em>Catalog not found</em>; a widget whose saved view is gone shows <em>Saved view not found</em>. The other widgets stay unaffected.</li><li>Widgets that overlap are marked with a red border and the note <em>Overlaps another widget</em>.</li></ul><h2 id="change-a-dashboard" tabindex="-1">Change a dashboard <a class="header-anchor" href="#change-a-dashboard" aria-label="Permalink to “Change a dashboard”">​</a></h2><p>If you may change a dashboard, the page has the button <em>Edit</em>. In the edit mode you can:</p><ul><li><strong>Add widget</strong>: choose the type <em>Text</em> or <em>Table</em>, enter a title of 1 to 150 characters and configure it (see below). New widgets go below the existing ones and can then be arranged. A dashboard has at most 50 widgets.</li><li><strong>Edit</strong> or <strong>Remove</strong> a widget with the buttons in its header. The type of a widget cannot change; remove it and add a new one.</li><li><strong>Rename</strong> the dashboard, change its description, or <strong>Share with everyone</strong>: a personal dashboard becomes shared, if you hold <code>dashboard:manage</code>, the name is free among the shared dashboards, and no widget shows a personal catalog. A shared dashboard does not become personal again.</li><li><strong>Delete</strong> the dashboard with all its widgets, after a confirmation.</li></ul><p>Choose <em>Done</em> to leave the edit mode.</p><h3 id="text-widgets" tabindex="-1">Text widgets <a class="header-anchor" href="#text-widgets" aria-label="Permalink to “Text widgets”">​</a></h3><p>A text widget holds Markdown of up to 10000 characters, for example methodological notes: bold and italic text, lists, quotes, headings, tables and links. Links work with <code>http</code>, <code>https</code> and <code>mailto</code> only. Raw HTML is not interpreted; it appears as text. Scripts, event handlers and other schemes such as <code>javascript:</code> never run.</p><h3 id="table-widgets" tabindex="-1">Table widgets <a class="header-anchor" href="#table-widgets" aria-label="Permalink to “Table widgets”">​</a></h3><p>A table widget needs a catalog you may see. On a shared dashboard only shared catalogs can be chosen, so that every reader sees data; a personal dashboard can also show your personal catalogs. Optionally choose a saved view of that catalog for its columns, and the rows per page (5 to 100, default 10). The widget always reads current data through the catalog query, as the reader.</p><h2 id="arrange-the-widgets" tabindex="-1">Arrange the widgets <a class="header-anchor" href="#arrange-the-widgets" aria-label="Permalink to “Arrange the widgets”">​</a></h2><p>The grid has 12 columns. A widget has a column, a width, a row and a height:</p><table tabindex="0"><thead><tr><th>Property</th><th>Allowed values</th></tr></thead><tbody><tr><td>Column</td><td>1 to 12</td></tr><tr><td>Width</td><td>1 to 12; column + width is at most 13</td></tr><tr><td>Row</td><td>1 to 500</td></tr><tr><td>Height</td><td>1 to 6 rows</td></tr></tbody></table><p>In the edit mode:</p><ul><li><strong>Drag</strong> a widget by the handle at the left of its title to move it, and drag the corner at the bottom right to resize it.</li><li>Or use the <strong>arrangement buttons</strong> below a widget (move left, right, up, down; one column narrower or wider; one row shorter or taller), or the <strong>arrow keys</strong> on the handle: arrow keys move the widget, with Shift they resize it.</li></ul><p>Every change is saved at once, as one request. If a widget would reach beyond column 12, the page says <em>Widget exceeds the grid width</em> and does not save the position. Overlaps are allowed; the editor marks them.</p><h2 id="changes-by-several-people" tabindex="-1">Changes by several people <a class="header-anchor" href="#changes-by-several-people" aria-label="Permalink to “Changes by several people”">​</a></h2><p>Every change refers to the version of the dashboard you have loaded. If someone else changed the dashboard in the meantime, the page reloads it and says so; repeat your change.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to “API”">​</a></h2><p>The dashboards are available through <code>/dashboards</code> and <code>/views/dashboards</code> (see the <a href="./../api/">API reference</a>):</p><ul><li><code>GET /dashboards</code> and <code>POST /dashboards</code> list and create dashboards; <code>PUT</code> and <code>DELETE /dashboards/{id}</code> change and delete one.</li><li><code>POST /dashboards/{id}/widgets</code>, <code>PUT</code> and <code>DELETE /dashboards/{id}/widgets/{widgetId}</code> change widgets, and <code>PUT /dashboards/{id}/layout</code> positions up to 50 widgets in one request. Every write needs the header <code>If-Match</code> with the version that was read (<code>&quot;3&quot;</code>); without it the answer is 428, with another version 412. The answers carry the new version as <code>ETag</code>.</li><li><code>GET /views/dashboards/{id}</code> returns the configuration, <code>GET /views/dashboards/{id}/data</code> the data of all widgets, and <code>GET /views/dashboards/{id}/widgets/{widgetId}/data?page=</code> another page of a table widget (from 0).</li><li>A taken name answers 422 with the problem type <code>urn:oea:problem:dashboard-name-taken</code>; other invalid input answers 422 with <code>invalidFields</code>. The personal dashboard of another person answers 404.</li></ul>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};